'use client';

import * as React from 'react';
import {
  motion,
  type TargetAndTransition,
  type Transition,
} from 'motion/react';

import {
  motionTokens,
  useShouldReduceMotion,
  useTempoTransition,
} from '../utils/motion';
import { useStaggeredEnter } from './stagger';

const POPOVER_TRANSITION = motionTokens.spring.pop;
const MENU_TRANSITION = motionTokens.transition.menu;
const MORPH_TRANSITION = motionTokens.spring.morph;

const HIDDEN_SCALE = {
  tooltip: motionTokens.scale.tooltip,
  popover: motionTokens.scale.popover,
  menu: motionTokens.scale.menu,
} as const;
const DEFAULT_TRANSITION = {
  tooltip: POPOVER_TRANSITION,
  popover: POPOVER_TRANSITION,
  menu: MENU_TRANSITION,
} as const;

type AnchoredKind = keyof typeof HIDDEN_SCALE;

type AnchoredAnimationProps = {
  transition?: Transition;
  exitTransition?: Transition;
};

type AnchoredMotionOptions = AnchoredAnimationProps & {
  kind?: AnchoredKind;
  open: boolean;
  keepMounted?: boolean;
  instant?: boolean;
};

type AnchoredMotionProps = {
  initial: false | TargetAndTransition;
  animate: TargetAndTransition;
  exit: TargetAndTransition;
  style?: React.CSSProperties;
  onAnimationComplete?: (definition: unknown) => void;
};

const WARM_WINDOW = 300;

const tooltipGroup = {
  open: new Set<symbol>(),
  warm: false,
  coolDown: undefined as ReturnType<typeof setTimeout> | undefined,
  leaving: new Map<symbol, () => void>(),
};

function useWarmTooltip(open: boolean, enabled: boolean) {
  const [id] = React.useState(() => Symbol('tooltip'));
  const [change, setChange] = React.useState(() => ({
    open,
    atOnce: enabled && open && tooltipGroup.warm,
  }));
  if (change.open !== open) {
    setChange({
      open,
      atOnce:
        enabled &&
        (open
          ? tooltipGroup.warm
          : [...tooltipGroup.open].some((other) => other !== id)),
    });
  }
  const [cut, setCut] = React.useState(false);
  if (open && cut) setCut(false);
  const atOnceRef = React.useRef(change.atOnce);
  React.useLayoutEffect(() => {
    atOnceRef.current = change.atOnce;
  });

  React.useEffect(() => {
    if (!enabled || !open) return;
    tooltipGroup.open.add(id);
    tooltipGroup.warm = true;
    clearTimeout(tooltipGroup.coolDown);
    if (atOnceRef.current)
      for (const hide of tooltipGroup.leaving.values()) hide();
    return () => {
      tooltipGroup.open.delete(id);
      if (tooltipGroup.open.size > 0) return;
      clearTimeout(tooltipGroup.coolDown);
      tooltipGroup.coolDown = setTimeout(() => {
        tooltipGroup.warm = false;
      }, WARM_WINDOW);
    };
  }, [enabled, open, id]);

  React.useEffect(() => {
    if (!enabled || open) return;
    tooltipGroup.leaving.set(id, () => setCut(true));
    return () => {
      tooltipGroup.leaving.delete(id);
    };
  }, [enabled, open, id]);

  return {
    appearAtOnce: open && change.atOnce,
    hideAtOnce: !open && (change.atOnce || cut),
  };
}

function useAnchoredMotion({
  kind = 'popover',
  open,
  keepMounted,
  instant,
  transition,
  exitTransition,
}: AnchoredMotionOptions): AnchoredMotionProps {
  const reduce = useShouldReduceMotion();
  const warmsUp = kind === 'tooltip' && instant === undefined;
  const warm = useWarmTooltip(open, warmsUp);
  const enter = useTempoTransition(transition ?? DEFAULT_TRANSITION[kind]);
  const leave = useTempoTransition(
    exitTransition ?? transition ?? DEFAULT_TRANSITION[kind],
  );
  const quick = useStaggeredEnter(enter);
  const hidden = { opacity: 0, scale: reduce ? 1 : HIDDEN_SCALE[kind] };
  const shown = { opacity: 1, scale: 1 };
  const none = { duration: 0 };

  const [settledClosed, setSettledClosed] = React.useState(
    Boolean(keepMounted) && !open,
  );
  if (open && settledClosed) setSettledClosed(false);

  const appearAtOnce = instant || warm.appearAtOnce;

  return {
    initial: appearAtOnce || !open ? false : hidden,
    animate: open
      ? {
          ...shown,
          transition: appearAtOnce ? none : kind === 'menu' ? quick : enter,
          ...(keepMounted && { visibility: 'visible' }),
        }
      : {
          ...hidden,
          transition: instant ? none : leave,
          ...(keepMounted && settledClosed && { visibility: 'hidden' }),
        },
    exit: { ...hidden, transition: instant ? none : leave },
    style: warm.hideAtOnce ? { visibility: 'hidden' } : undefined,
    onAnimationComplete: keepMounted
      ? (definition) => {
          const target = definition as { opacity?: number };
          if (!open && target.opacity === 0) setSettledClosed(true);
        }
      : undefined,
  };
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type AnyComponent = string | React.ComponentType<any>;
const motionComponents = new Map<AnyComponent, AnyComponent>();

function motionFor(type: AnyComponent): AnyComponent {
  let component = motionComponents.get(type);
  if (!component) {
    component =
      typeof type === 'string'
        ? (motion as unknown as Record<string, AnyComponent>)[type]!
        : (motion.create(type) as AnyComponent);
    motionComponents.set(type, component);
  }
  return component;
}

function mergeRefs<T>(...refs: (React.Ref<T> | undefined)[]) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === 'function') ref(node);
      else if (ref) (ref as React.RefObject<T | null>).current = node;
    }
  };
}

type ElementProps = {
  ref?: React.Ref<HTMLElement>;
  style?: React.CSSProperties;
} & Record<string, unknown>;

function asMotion(element: React.ReactElement, props: ElementProps) {
  const own = element.props as ElementProps;
  const Component = motionFor(
    element.type as AnyComponent,
  ) as React.ElementType;
  return (
    <Component
      {...own}
      {...props}
      ref={mergeRefs(own.ref, props.ref)}
      style={{ ...own.style, ...props.style }}
    />
  );
}

export {
  useAnchoredMotion,
  asMotion,
  mergeRefs,
  POPOVER_TRANSITION,
  MENU_TRANSITION,
  MORPH_TRANSITION,
  HIDDEN_SCALE,
  type AnchoredKind,
  type AnchoredAnimationProps,
  type AnchoredMotionProps,
};

'use client';

import * as React from 'react';
import type { Transition } from 'motion/react';

import {
  motionTokens,
  toCssTiming,
  useShouldReduceMotion,
  useTempoTransition,
} from '../utils/motion';
import { curveFrom, velocityOf, INSTANT, type Run } from './momentum';

type Box = { x: number; y: number; width: number; height: number };

type IndicatorSnapshot = Box & {
  version: number;
  item: Element;
  className: string;
  attributes: Record<string, string>;
};

const SKIPPED_ATTRIBUTE =
  /^data-(slot|testid|animate-ui-.*|hovered|pressed|focused|focus-visible|highlighted|rac|react-aria-.*|key|radix-.*|composite-.*)$/;

const NONE = (value: string) => !value || value === 'none';

function layoutSizeOf(element: HTMLElement) {
  const style = getComputedStyle(element);
  let width = parseFloat(style.width);
  let height = parseFloat(style.height);
  if (!Number.isFinite(width) || !Number.isFinite(height))
    return { width: element.offsetWidth, height: element.offsetHeight };
  if (style.boxSizing !== 'border-box') {
    const px = (value: string) => parseFloat(value) || 0;
    width +=
      px(style.paddingLeft) +
      px(style.paddingRight) +
      px(style.borderLeftWidth) +
      px(style.borderRightWidth);
    height +=
      px(style.paddingTop) +
      px(style.paddingBottom) +
      px(style.borderTopWidth) +
      px(style.borderBottomWidth);
  }
  return { width, height };
}

function containerScale(container: HTMLElement, rect: DOMRect) {
  const { width, height } = layoutSizeOf(container);
  return {
    x: width && Math.abs(rect.width - width) > 0.01 ? rect.width / width : 1,
    y:
      height && Math.abs(rect.height - height) > 0.01
        ? rect.height / height
        : 1,
  };
}

function lengthOf(value: string, size: number) {
  if (value.endsWith('%')) return (parseFloat(value) / 100) * size;
  if (value.endsWith('px') || /^-?[\d.]+$/.test(value))
    return parseFloat(value);
  return null;
}

function untransform(element: Element, box: Box): Box {
  const style = getComputedStyle(element);
  if (NONE(style.translate) && NONE(style.scale) && NONE(style.transform))
    return box;
  if (!NONE(style.rotate)) return box;
  let [a, d, e, f] = [1, 1, 0, 0];
  if (!NONE(style.transform)) {
    const matrix = style.transform.match(/^matrix\(([^)]+)\)$/);
    if (!matrix) return box;
    const [ma = 1, mb = 0, mc = 0, md = 1, me = 0, mf = 0] = matrix[1]!
      .split(',')
      .map(Number);
    if (Math.abs(mb) > 1e-6 || Math.abs(mc) > 1e-6) return box;
    [a, d, e, f] = [ma, md, me, mf];
  }
  const scale = NONE(style.scale) ? [] : style.scale.split(/\s+/).map(Number);
  const sx = scale[0] ?? 1;
  const sy = scale[1] ?? sx;
  const [kx, ky] = [sx * a, sy * d];
  if (!kx || !ky || ![kx, ky].every(Number.isFinite)) return box;
  const width = box.width / kx;
  const height = box.height / ky;
  const [tX = '0px', tY = '0px'] = NONE(style.translate)
    ? []
    : style.translate.split(/\s+(?![^(]*\))/);
  const tx = lengthOf(tX, width);
  const ty = lengthOf(tY, height);
  const [oX = '0px', oY = '0px'] = style.transformOrigin.split(/\s+/);
  const ox = lengthOf(oX, width);
  const oy = lengthOf(oY, height);
  if (tx === null || ty === null || ox === null || oy === null) return box;
  return {
    x: box.x - ox - tx - sx * (e - a * ox),
    y: box.y - oy - ty - sy * (f - d * oy),
    width,
    height,
  };
}

function boxIn(
  container: HTMLElement,
  element: Element,
  untransformed = false,
): Box {
  const containerRect = container.getBoundingClientRect();
  const rect = element.getBoundingClientRect();
  const scale = containerScale(container, containerRect);
  const box = {
    x:
      (rect.left - containerRect.left) / scale.x -
      container.clientLeft +
      container.scrollLeft,
    y:
      (rect.top - containerRect.top) / scale.y -
      container.clientTop +
      container.scrollTop,
    width: rect.width / scale.x,
    height: rect.height / scale.y,
  };
  return untransformed ? untransform(element, box) : box;
}

function isTransformed(container: HTMLElement) {
  const rect = container.getBoundingClientRect();
  const { width, height } = layoutSizeOf(container);
  return (
    Math.abs(rect.width - width) > 0.01 || Math.abs(rect.height - height) > 0.01
  );
}

const sameBox = (a: Box, b: Box) =>
  Math.abs(a.x - b.x) < 0.01 &&
  Math.abs(a.y - b.y) < 0.01 &&
  Math.abs(a.width - b.width) < 0.01 &&
  Math.abs(a.height - b.height) < 0.01;

type BoxOf = (item: HTMLElement, container: HTMLElement) => Element;

type SlidingIndicatorConfig = {
  findActive: (container: HTMLElement) => HTMLElement | null;
  items: string;
  attributes: string[];
  style: { href: string; css: string };
  slot: string;
  reducedMotion?: 'jump' | 'fade';
  untransformed?: boolean;
  zIndex?: number;
  fadeBackground?: boolean;
};

function readSnapshot(
  container: HTMLElement,
  previous: IndicatorSnapshot | null,
  {
    copy,
    boxOf,
    config,
  }: { copy: boolean; boxOf?: BoxOf; config: SlidingIndicatorConfig },
): IndicatorSnapshot | null {
  const item = config.findActive(container);
  if (!item) return null;

  const box = boxIn(
    container,
    boxOf?.(item, container) ?? item,
    config.untransformed,
  );
  const attributes: Record<string, string> = {};
  if (copy) {
    for (const { name, value } of item.attributes) {
      if (name.startsWith('data-') && !SKIPPED_ATTRIBUTE.test(name))
