  return () => cancelAnimationFrame(frame);
}

const SLIDING_ATTRIBUTE = 'data-animate-ui-sliding';
const LEAVING_ATTRIBUTE = 'data-animate-ui-leaving';

const placement = (
  box: Box,
  zIndex: number,
