  const slideRef = React.useRef<Slide | null>(null);
  const crossfadesRef = React.useRef<Crossfades>({
    copies: new Map(),
    fadeIn: null,
  });
  const restRef = React.useRef<{
    version: number;
    box: Box;
    className: string;
    attributes: Record<string, string>;
  } | null>(null);
