    else if (typeof value === 'number' && key === 'stiffness')
      scaled[key] = value / (tempo * tempo);
    else if (typeof value === 'number' && key === 'damping')
      scaled[key] = value / tempo;
    else if (value && typeof value === 'object' && !Array.isArray(value))
      scaled[key] = scaleTransition(value as Transition, tempo);
    else scaled[key] = value;
  }
  return scaled as T;
}

function useTempoTransition<T extends Transition | undefined>(
  transition: T,
): T {
  const { tempo } = React.use(MotionTokensContext);
  return scaleTransition(transition, tempo);
}

function useMotionTokens(): MotionTokens {
  return React.use(MotionTokensContext);
}

type CheckAnimation = 'draw' | 'pop';

const CheckAnimationContext = React.createContext<CheckAnimation>('draw');

function useCheckAnimation(own?: CheckAnimation): CheckAnimation {
  const inherited = React.use(CheckAnimationContext);
  return own ?? inherited;
}

type CssTiming = { duration: number; easing: string };

const CSS_EASINGS: Record<string, string> = {
  linear: 'linear',
  easeIn: 'cubic-bezier(0.42, 0, 1, 1)',
  easeOut: 'cubic-bezier(0, 0, 0.58, 1)',
  easeInOut: 'cubic-bezier(0.42, 0, 0.58, 1)',
  circIn: 'cubic-bezier(0, 0.65, 0.55, 1)',
  circOut: 'cubic-bezier(0.55, 0, 1, 0.45)',
  backIn: 'cubic-bezier(0.31, 0.01, 0.66, -0.59)',
  backOut: 'cubic-bezier(0.33, 1.53, 0.69, 0.99)',
};

const SPRING_KEYS = [
  'stiffness',
  'damping',
  'mass',
  'bounce',
  'visualDuration',
];

function toCssEase(curve: unknown): string {
  if (
    Array.isArray(curve) &&
    curve.length === 4 &&
    curve.every(Number.isFinite)
  )
    return `cubic-bezier(${curve.join(', ')})`;
  if (typeof curve === 'string') return CSS_EASINGS[curve] ?? 'ease';
  return CSS_EASINGS.easeInOut!;
}

function toCssTiming(motionTransition: Transition): CssTiming {
  const options = motionTransition as Record<string, unknown>;
  const isSpring =
    options.type === 'spring' || SPRING_KEYS.some((key) => key in options);

  if (isSpring) {
    const springOptions =
      typeof options.duration === 'number'
        ? { ...options, duration: options.duration * 1000 }
        : options;
    const { duration, ease: curve } = createGeneratorEasing(
      springOptions,
      100,
      springGenerator,
    );
    const ms = Math.round(duration * 1000);
    return { duration: ms, easing: generateLinearEasing(curve, ms) };
  }

  const seconds = typeof options.duration === 'number' ? options.duration : 0.3;
  return {
    duration: Math.round(seconds * 1000),
    easing: toCssEase(options.ease),
  };
}

type ReducedMotion = 'user' | 'never' | 'always';

const ReducedMotionContext = React.createContext<ReducedMotion>('user');

function useReducedMotionSetting(): ReducedMotion {
  const own = React.use(ReducedMotionContext);
  const { reducedMotion } = React.use(MotionConfigContext);
  return reducedMotion === 'always' ? 'always' : own;
}

type ReducedMotionConfigProps = {
  children: React.ReactNode;
  remount?: boolean;
};

function ReducedMotionConfig({ children, remount }: ReducedMotionConfigProps) {
  const reducedMotion = useReducedMotionSetting();

  return (
    <MotionConfig reducedMotion={reducedMotion}>
      {remount ? <RemountOnReduce>{children}</RemountOnReduce> : children}
    </MotionConfig>
  );
}

function RemountOnReduce({ children }: { children: React.ReactNode }) {
  const reduce = useShouldReduceMotion();
  return (
    <React.Fragment key={reduce ? 'reduce' : 'full'}>{children}</React.Fragment>
  );
}

const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)';

function subscribeToReducedMotion(onChange: () => void) {
  const mql = window.matchMedia(REDUCED_MOTION_QUERY);
  mql.addEventListener('change', onChange);
  return () => mql.removeEventListener('change', onChange);
}

function useShouldReduceMotion() {
  const reducedMotion = useReducedMotionSetting();
  const prefersReduced = React.useSyncExternalStore(
    subscribeToReducedMotion,
    () => window.matchMedia(REDUCED_MOTION_QUERY).matches,
    () => false,
  );

  if (reducedMotion === 'never') return false;
  return reducedMotion === 'always' || prefersReduced;
}

export {
  createMotionTokens,
  motionTokens,
  MotionTokensContext,
  useMotionTokens,
  CheckAnimationContext,
  useCheckAnimation,
  ease,
  spring,
  transition,
  scale,
  blur,
  rotate,
  shift,
  stagger,
  ReducedMotionConfig,
  useShouldReduceMotion,
  useReducedMotionSetting,
  ReducedMotionContext,
  scaleTransition,
  useTempoTransition,
  toCssTiming,
  type CssTiming,
  type ReducedMotionConfigProps,
  type MotionTokens,
  type CheckAnimation,
  type ReducedMotion,
};

'use client';

import {
  createGeneratorEasing,
  generateLinearEasing,
  spring as springGenerator,
  type Transition,
} from 'motion/react';

import { toCssTiming } from '../utils/motion';

type Curve = {
  duration: number;
  easing: string;
  at(time: number): number;
  speed(time: number): number;
  initial: number;
};

type Run = { offset: number[]; curve: Curve };

const INSTANT: Curve = {
  duration: 0,
  easing: 'linear',
  at: () => 1,
  speed: () => 0,
  initial: 0,
};

const SLACK = 0.002;

const SPRING_KEYS = [
  'stiffness',
  'damping',
  'mass',
  'bounce',
  'visualDuration',
];

const isSpring = (options: Record<string, unknown>) =>
  options.type === 'spring' || SPRING_KEYS.some((key) => key in options);

function shapeOf(transition: Transition, speed: number) {
  const options = transition as Record<string, unknown>;
  if (!isSpring(options)) return null;
  const { ease, duration: seconds } = createGeneratorEasing(
    {
      ...options,
      ...(typeof options.duration === 'number'
        ? { duration: options.duration * 1000 }
        : null),
      velocity: speed * 100_000,
    },
    100,
    springGenerator,
  );
  const duration = Math.round(seconds * 1000);
  let peak = 1;
  let trough = 0;
  for (let time = 0; time <= duration; time += 5) {
    const progress = ease(time / duration);
    peak = Math.max(peak, progress);
    trough = Math.min(trough, progress);
  }
  return { ease, duration, peak, trough };
}

function curveOf(transition: Transition, initial = 0): Curve {
  const shape = shapeOf(transition, initial);
  if (!shape) {
    const { duration, easing } = toCssTiming(transition);
    return {
      duration,
      easing,
      at: (time) => (time >= duration ? 1 : Math.max(0, time / duration)),
      speed: () => 0,
      initial: 0,
    };
  }
  const { ease, duration } = shape;
  if (duration === 0) return INSTANT;
  const step = 0.5;
  return {
    duration,
    easing: generateLinearEasing(ease, duration),
    at: (time) => (time >= duration ? 1 : ease(Math.max(0, time) / duration)),
    speed(time) {
      if (!(time >= 0) || time >= duration) return 0;
      if (time === 0) return initial;
      if (ease(time / duration) === 1) return 0;
      const before = Math.max(0, time - step);
      let after = Math.min(duration, time + step);
      if (ease(after / duration) === 1) after = time;
      return after > before
        ? (ease(after / duration) - ease(before / duration)) / (after - before)
        : initial;
    },
    initial,
  };
}

function carries(curve: Curve, offset: number[]) {
  return curve.initial * Math.hypot(...offset) > 0.001;
}

function velocityOf(run: Run, time: number) {
  const speed = run.curve.speed(time);
  return run.offset.map((offset) => -offset * speed);
}

function startOf(transition: Transition, offset: number[], velocity: number[]) {
  let length = 0;
  let along = 0;
  offset.forEach((value, i) => {
    length += value * value;
    along += value * (velocity[i] ?? 0);
  });
  const speed = length < 0.25 ? 0 : -along / length;
  const rest = shapeOf(transition, 0);
  if (!rest || speed <= 0) return 0;
  const within = (share: number) => {
    const shape = shapeOf(transition, speed * share)!;
    return (
      shape.trough >= -SLACK && shape.peak <= Math.max(rest.peak, 1) + SLACK
    );
  };
  if (within(1)) return speed;
  let low = 0;
  let high = 1;
  for (let i = 0; i < 8; i++) {
    const share = (low + high) / 2;
    if (within(share)) low = share;
    else high = share;
  }
  return speed * low;
}

function curveFrom(
  transition: Transition,
  offset: number[],
  velocity: number[],
): Curve {
  return curveOf(transition, startOf(transition, offset, velocity));
}

export {
  carries,
  curveFrom,
  curveOf,
  startOf,
  velocityOf,
  INSTANT,
  type Curve,
  type Run,
};

import * as React from 'react';
import type { Transition } from 'motion/react';

import {
  motionTokens,
  toCssTiming,
  useShouldReduceMotion,
  useTempoTransition,
} from '../utils/motion';

const ROWS = [
  '[role^="menuitem"]',
  '[role="option"]',
  '[role="separator"]',
  '[data-slot$="-label"]',
  '[data-slot="navigation-menu-link"]',
  '[data-slot="sidebar-menu-sub-item"]',
].join(',');

const STAGGER = { duration: 0.3, ease: motionTokens.ease.soft, delay: 0.033 };
const SHIFT = 8;
const ARRIVE = { duration: 0.1, ease: motionTokens.ease.out };
const CALM = 10;
const STAGGER_ID = 'animate-ui-stagger';

type StaggerTiming = { duration: number; easing: string; step: number };

function opacityOf(el: Element) {
  let opacity = 1;
  for (let node: Element | null = el; node; node = node.parentElement)
    opacity *= Number(getComputedStyle(node).opacity);
  return opacity;
}

function rowsOf(root: HTMLElement) {
  const rows = [...root.querySelectorAll<HTMLElement>(ROWS)].filter(
    (row) => !row.closest('[data-animate-ui-handoff]'),
  );
  return rows.filter(
    (row) => !rows.some((other) => other !== row && other.contains(row)),
  );
}

function animateRows(rows: HTMLElement[], timing: StaggerTiming) {
  const shift =
    rows[0] && getComputedStyle(rows[0]).direction === 'rtl' ? -SHIFT : SHIFT;
  const step =
    rows.length > CALM
      ? timing.step * Math.sqrt(CALM / rows.length)
      : timing.step;
  return rows.map((row, index) =>
    row.animate(
      [
        {
          opacity: 0,
          filter: motionTokens.blur.surface,
          translate: `${shift}px 0`,
        },
        // No opacity here: it ends on the row's own, a disabled one's 50% or one the library shows late.
        { filter: 'blur(0px)', translate: '0 0' },
      ],
      {
        duration: timing.duration,
        easing: timing.easing,
        delay: index * step,
        fill: 'backwards',
        id: STAGGER_ID,
      },
    ),
  );
}

/** How long until `row` lands from its stagger (0 when it isn't staggering). */
function staggerLeft(row: Element | null) {
  const animation = row
    ?.getAnimations()
    .find((candidate) => candidate.id === STAGGER_ID);
  if (!animation || animation.playState === 'finished') return 0;
  const end = animation.effect?.getComputedTiming().endTime;
  return Math.max(0, Number(end ?? 0) - Number(animation.currentTime ?? 0));
}

/**
 * A just-opened list's rows slide in from the side one after another, out of a blur;
 * rows a library renders a commit later (React Aria's) as they come, before
 * they're painted. `stop` shows them all.
 */
/**
 * Rows slid aside widen what their list can scroll: a library scrolling the
 * chosen one into view (Base UI's combobox) would scroll sideways too, then
 * back as they land. The lists keep their horizontal scroll meanwhile.
 */
function holdScrollX(root: HTMLElement) {
  const lefts = new Map<Element, number>();
  for (const el of [root, ...root.querySelectorAll('*')])
    lefts.set(el, el.scrollLeft);
  const hold = (event: Event) => {
    const target = event.target as Element;
    const left = lefts.get(target);
    if (left !== undefined && target.scrollLeft !== left)
      target.scrollLeft = left;
  };
  root.addEventListener('scroll', hold, true);
  return () => root.removeEventListener('scroll', hold, true);
}

function staggerRows(root: HTMLElement, timing: StaggerTiming) {
  let animations: Animation[] = [];
  let observer: MutationObserver | null = null;
  const release = holdScrollX(root);
  const start = (rows: HTMLElement[]) => {
    animations = animateRows(rows, timing);
    void Promise.all(animations.map((animation) => animation.finished)).then(
      release,
      release,
    );
  };
  const rows = rowsOf(root);
  if (rows.length) start(rows);
  else {
    observer = new MutationObserver(() => {
      const late = rowsOf(root);
      if (!late.length) return;
      observer?.disconnect();
      observer = null;
      start(late);
    });
    observer.observe(root, { childList: true, subtree: true });
    setTimeout(() => {
      if (!observer) return;
      observer.disconnect();
      release();
    }, 300);
  }
  return () => {
    observer?.disconnect();
    for (const animation of animations) animation.finish();
    release();
  };
}

/** Staggers `el`'s rows if it opens from closed: it's still transparent. */
function staggerFromClosed(el: HTMLElement, timing: StaggerTiming) {
  return opacityOf(el) > 0.05 ? null : staggerRows(el, timing);
}

function useStaggerTiming() {
  const transition = useTempoTransition(STAGGER);
  const timingRef = React.useRef<StaggerTiming>(null!);
  React.useLayoutEffect(() => {
    timingRef.current = {
      ...toCssTiming(transition),
      step: (transition.delay ?? 0) * 1000,
    };
  });
  return timingRef;
}

/**
 * Staggers the rows of `ref`'s list as it opens from closed (it starts
 * transparent, or `fresh` says so), not as it comes back while closing or
 * takes over another menu's popover.
 */
function useStaggerOnOpen(
  ref: React.RefObject<HTMLElement | null>,
  open: boolean,
  options: {
    skip?: boolean;
    fresh?: boolean;
    closed?: (el: HTMLElement) => boolean;
  } = {},
) {
  const reduce = useShouldReduceMotion();
  const timingRef = useStaggerTiming();
  const {
    skip = false,
    fresh,
    closed = (el) => opacityOf(el) <= 0.05,
  } = options;
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!open || reduce || skip || !el) return;
    if (fresh === undefined ? !closed(el) : !fresh) return;
    return staggerRows(el, timingRef.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps, @eslint-react/exhaustive-deps
  }, [open]);
}

/** A sidebar's submenu, in a collapsible panel: its sub-items stagger as it unfolds from closed. */
function useSubmenuStagger(
  ref: React.RefObject<HTMLElement | null>,
  open: boolean,
) {
  useStaggerOnOpen(ref, open, {
    closed: (el) =>
      el.offsetHeight < 1 &&
      !!el.querySelector('[data-slot="sidebar-menu-sub"]'),
  });
}

/** A list whose rows stagger: its box is there at once (opacity), its rows bring the fade; under reduced motion, nothing staggers and it fades. */
function useStaggeredEnter(enter: Transition): Transition {
  const reduce = useShouldReduceMotion();
  const arrive = useTempoTransition(ARRIVE);
  return reduce ? enter : { ...enter, opacity: arrive };
}

/**
 * A sidebar submenu's panel is there at once (opacity, blur) while it unfolds,
 * so its sub-items bring the fade: added over the panel's own animation, after it starts.
 */
function quickSubmenuPanel(el: HTMLElement | null) {
  if (!el?.querySelector('[data-slot="sidebar-menu-sub"]')) return;
  queueMicrotask(() => {
    const ends = el
      .getAnimations()
      .map((animation) =>
        Number(animation.effect?.getComputedTiming().endTime ?? 0),
      );
    const total = Math.max(300, ...ends);
    const settled = { opacity: 1, filter: 'blur(0px)' };
    el.animate(
      [
        { ...settled, offset: Math.min(1, 100 / total) },
        { ...settled, offset: 1 },
      ],
      { duration: total, easing: 'ease-out' },
    );
  });
}

export {
  quickSubmenuPanel,
  staggerFromClosed,
  useStaggeredEnter,
  staggerLeft,
  useSubmenuStagger,
  staggerRows,
  useStaggerOnOpen,
  useStaggerTiming,
  type StaggerTiming,
};

